// The home-screen widgets' native texts and looks (docs/widgets-spec.md; generated by scripts/brand/widget-native.mjs):
// both apps carry the same words in all 13 languages, none with a dash, and the old Style setting is gone.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import fs from 'node:fs'

const root = new URL('../', import.meta.url)
const read = p => fs.readFileSync(new URL(p, root), 'utf8')
const LANGS = ['en', 'de', 'fr', 'es', 'it', 'nl', 'pl', 'cs', 'sl', 'pt', 'ja', 'zh', 'ko']
const JAVA = read('mobile/android/app/src/main/java/app/metablend/widget/WidgetText.java')
const SWIFT = read('mobile/ios/App/MetaBlendWidgets/WidgetLook.swift')
const strings = s => [...s.matchAll(/"((?:[^"\\]|\\.)*)"/g)].map(m => JSON.parse(`"${m[1]}"`))

// lang → [home, openOnce, pickCity, planHike, offline], the four messages and "Home city" both apps show
const rows = (src, re) => Object.fromEntries([...src.matchAll(re)].map(m => [m[1], strings(m[2])]))
const java = rows(JAVA, /T\.put\("(\w+)", new String\[\] \{ (.*) \}\);/g)
const swift = rows(SWIFT, /^\s+"(\w+)": \[(.*)\],$/gm)

test('widget texts: all 13 languages in both apps, the same words', () => {
  assert.deepEqual(Object.keys(java).sort(), [...LANGS].sort())
  assert.deepEqual(Object.keys(swift).sort(), [...LANGS].sort())
  for (const lang of LANGS) {
    // settings, city, home, show, hours, days, save, the 4 messages, then the 10 spoken labels of the drawn icons
    const j = java[lang]
    assert.equal(j.length, 21, lang)
    assert.deepEqual(swift[lang], [j[2], ...j.slice(7)], lang)
    for (const text of j) assert.ok(text.trim(), `${lang}: an empty text`)
  }
  // Japanese, Chinese and Korean are their own, never the English row
  for (const lang of ['ja', 'zh', 'ko']) for (let i = 0; i < 21; i++) assert.notEqual(java[lang][i], java.en[i], `${lang}[${i}]`)
})

// the drawn icons' spoken labels (VoiceOver, TalkBack) are the app's own words, in the same 13 languages
const A11Y = { clear: 'cClear', partlyCloudy: 'cPartlyCloudy', cloudy: 'cCloudy', fog: 'cFog', showers: 'cShowers', rain: 'cRain', snow: 'cSnow', thunder: 'cThunder', wind: 'windLabel', summit: 'appIconSummit' }

test('widget icons: the spoken labels are the app\'s own words in all 13 languages', async () => {
  for (const lang of LANGS) {
    const pack = (await import(new URL(`lib/i18n/${lang}.js`, root))).default
    assert.deepEqual(java[lang].slice(11), Object.values(A11Y).map(k => pack[k]), lang)
    for (const w of java[lang].slice(11)) assert.doesNotMatch(w, /\p{Extended_Pictographic}/u, `${lang}: ${w}`)
  }
})

test('widget icons: both apps read each weather drawing as the same condition', () => {
  const cases = (src, fn) => {
    const body = src.slice(src.indexOf(fn)).split(/\n\s*default:/)[0]
    const map = {}
    for (const line of body.split('\n')) {
      const m = line.match(/^\s*case (.*): return "?\.?(\w+)"?;?\s*$/) // Java: case "☀": case "🌙": return "clear"; Swift: case "☀", "🌙": return .clear
      if (m) for (const e of m[1].matchAll(/"([^"]+)"/g)) map[e[1]] = m[2]
    }
    return map
  }
  const java = cases(read('mobile/android/app/src/main/java/app/metablend/widget/WidgetRenderer.java'), 'static String conditionKey(')
  const swift = cases(read('mobile/ios/App/MetaBlendWidgets/MetaBlendWidgets.swift'), 'static func condition(')
  assert.deepEqual(java, swift)
  // every emoji the website draws (app/components/Glyph.jsx) has a spoken condition
  const site = [...read('app/components/Glyph.jsx').matchAll(/'(\S{1,2})': \[/g)].map(m => m[1])
  assert.equal(site.length, 13)
  for (const e of site) assert.ok(java[e] in A11Y, `${e}: ${java[e]}`)
})

test('widget icons: a city widget\'s drawing stays silent only when the line under it says the same words', () => {
  // owner, 2026-11-16: "Lienz, 7°, Leicht bewölkt, Leicht bewölkt" reads the condition twice; a rain nowcast or a
  // later hour's rain in that line keeps the drawing's label, and nothing else ever goes silent
  const renderer = read('mobile/android/app/src/main/java/app/metablend/widget/WidgetRenderer.java')
  assert.match(renderer, /static boolean sameWords\(Look look, String emoji, String line\) \{[^}]*return !key\.isEmpty\(\) && look\.tx\.get\(key\)\.equals\(line\);/)
  const silenced = [...renderer.matchAll(/setContentDescription\((R\.id\.\w+|\w+), ""\)/g)].map(m => m[1])
  assert.deepEqual(silenced, ['R.id.glyph'])
  assert.match(renderer, /if \(sameWords\(look, now\.optString\("icon"\), now\.optString\("text"\)\)\) v\.setContentDescription\(R\.id\.glyph, ""\);/)
  const hikeViews = renderer.slice(renderer.indexOf('private static RemoteViews hikeViews'), renderer.indexOf('private static void finish'))
  assert.doesNotMatch(hikeViews, /sameWords/)

  const swift = read('mobile/ios/App/MetaBlendWidgets/MetaBlendWidgets.swift')
  assert.match(swift, /if line == look\.word\(key\) \{\s*drawing\(e\)\.accessibilityHidden\(true\)\s*\} else \{\s*drawing\(e\)\s*\.accessibilityElement\(children: \.ignore\)\s*\.accessibilityLabel\(look\.word\(key\)\)/)
  assert.match(swift, /let line: String\? = h == nil \? p\.now\.text : nil/)
  const glyphs = [...swift.matchAll(/Glyph\(emoji: ([^)]*)\)/g)].map(m => m[1])
  assert.equal(glyphs.filter(g => /line: line$/.test(g)).length, 3) // small, medium, large city widget
  for (const g of glyphs.filter(g => !/h\?\.icon \?\? p\.now\.icon/.test(g))) assert.doesNotMatch(g, /line:/, g) // hours, days, hike
})

test('widget icons: every drawn icon has a spoken label on both platforms', () => {
  // Android: each icon id in the layouts gets a content description in the renderer (glyph2 is the silent half of
  // partly cloudy; the scenery is not an icon)
  const renderer = read('mobile/android/app/src/main/java/app/metablend/widget/WidgetRenderer.java')
  const described = new Set([...renderer.matchAll(/setContentDescription\(R\.id\.(\w+)/g)].map(m => m[1]))
  assert.match(renderer, /setContentDescription\(a, look\.tx\.get\(conditionKey\(e\)\)\)/) // glyph and cell_glyph
  const layouts = fs.readdirSync(new URL('mobile/android/app/src/main/res/layout/', root)).filter(f => /^widget_(weather|hike|cell)/.test(f))
  for (const f of layouts) {
    const xml = read(`mobile/android/app/src/main/res/layout/${f}`)
    for (const m of xml.matchAll(/<ImageView android:id="@\+id\/(\w+)"[^>]*>/g)) {
      const [tag, id] = m
      if (/importantForAccessibility="no"/.test(tag)) continue
      assert.ok(id === 'glyph' || id === 'cell_glyph' || described.has(id), `${f}: ${id} has no spoken label`)
    }
  }
  assert.ok(described.has('cell_sub'), 'an hour\'s rain is read as "Rain 7%"')
  // iPhone: every Icon outside the weather glyph (which speaks for its drawings as one element) passes a label, and
  // the scenery behind the content is silent (an unlabelled Image is read by its file name)
  const swiftViews = read('mobile/ios/App/MetaBlendWidgets/MetaBlendWidgets.swift')
  const background = swiftViews.slice(swiftViews.indexOf('struct Background: View'), swiftViews.indexOf('struct Glyph: View'))
  assert.match(background, /\.clipShape\(ContainerRelativeShape\(\)\)\s*\.accessibilityHidden\(true\)/)
  assert.match(read('mobile/android/app/src/main/res/layout/widget_scenery.xml'), /importantForAccessibility="noHideDescendants"/)
  for (const line of swiftViews.split('\n').filter(l => /Icon\(name: "icon-/.test(l))) {
    assert.ok(/label: /.test(line) || /size: size, color/.test(line), `unlabelled: ${line.trim()}`)
  }
})

test('widget texts: no dashes, and the offline message is two sentences', () => {
  for (const lang of LANGS) {
    for (const text of java[lang]) assert.doesNotMatch(text, /[–—]/, `${lang}: ${text}`)
    assert.doesNotMatch(java[lang][10], / - /, lang)
  }
  assert.equal(java.en[10], 'No connection. Tap to open MetaBlend.')
  assert.equal(java.de[10], 'Keine Verbindung. Tippen, um MetaBlend zu öffnen.')
})

test('widget settings: the Style option (Living sky, System) is gone on both platforms', () => {
  const settings = read('mobile/android/app/src/main/java/app/metablend/widget/WidgetConfigActivity.java')
  assert.doesNotMatch(settings, /"style"|tx\.get\("sky"\)|tx\.get\("system"\)/)
  assert.doesNotMatch(JAVA, /"style"|"Living sky"/)
  const intents = read('mobile/ios/App/MetaBlendWidgets/AppIntent.swift')
  assert.doesNotMatch(intents, /WidgetStyle|"Style"/)
  const catalog = JSON.parse(read('mobile/ios/App/MetaBlendWidgets/Localizable.xcstrings')).strings
  for (const k of ['Style', 'Living sky', 'System']) assert.ok(!(k in catalog), k)
  assert.doesNotMatch(read('mobile/ios/App/MetaBlendWidgets/MetaBlendWidgets.swift'), /SkyBackground|palette\(sky:|WidgetStyle/)
})

test('widget themes: Default, Mono, Winter and Sky with every colour role, light and dark', () => {
  const ROLES = ['ink', 'muted', 'window', 'rain', 'sun', 'moon', 'cloud']
  for (const dir of ['values', 'values-night']) {
    const xml = read(`mobile/android/app/src/main/res/${dir}/widget_colors.xml`)
    for (const t of ['default', 'mono', 'winter', 'sky']) for (const r of ROLES) assert.match(xml, new RegExp(`name="w_${t}_${r}">#[0-9a-f]{6}<`), `${dir} ${t} ${r}`)
  }
  // gold only on the sun, green only on a window (spec section 2): no role but sun is gold, none but window green
  const light = read('mobile/android/app/src/main/res/values/widget_colors.xml')
  assert.match(light, /w_default_sun">#966400</)
  assert.match(light, /w_default_window">#117948</)
  assert.equal((SWIFT.match(/case \(\.(standard|mono|winter|sky), (true|false)\): return Palette/g) ?? []).length, 8)
})
